const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程 6x+5=2x+11' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '6x-2x=11-5' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '4x=6' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x=6/4=3/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;

    function rectPath(x, y, w, h) {
      var c = visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h]]);
      if (!c.length || String(c[c.length - 1]).toUpperCase() !== 'Z') {
        c.push('Z');
      }
      return c;
    }

    function downArrowPath(x1, y1, x2, y2) {
      var shaft = visualSdk.polyline([[x1, y1], [x2, y2]]);
      var head = visualSdk.polyline([[x2 - 6, y2 - 9], [x2, y2], [x2 + 6, y2 - 9]]);
      return shaft.concat(head);
    }

    var margin = Math.max(12, W * 0.05);
    var cardW = W - margin * 2;
    var topArea = 62;
    var bottom = 20;
    var gap = 26;
    var cardH = (H - topArea - bottom - gap * 2) / 3;
    if (cardH < 54) {
      gap = 14;
      cardH = (H - topArea - bottom - gap * 2) / 3;
    }
    if (cardH < 30) { cardH = 30; }

    var titleFs = Math.min(21, Math.max(14, W * 0.048));
    var nameFs = Math.min(17, Math.max(12, W * 0.04));
    var eqFs = Math.min(24, Math.max(15, W * 0.055));
    var numFs = Math.min(16, Math.max(11, W * 0.038));

    var ink = '#1f3148';
    var accent = '#2f6fbf';
    var paths = [];
    var children = [];
    var i;
    var j;

    paths.push({ id: 'bg', commands: rectPath(0, 0, W, H) });
    children.push({ type: 'path', pathId: 'bg', fill: '#ffffff' });

    paths.push({ id: 'rule', commands: visualSdk.polyline([[margin, topArea - 16], [W - margin, topArea - 16]]) });
    children.push({ type: 'path', pathId: 'rule', fill: 'none', stroke: { width: 2, color: accent } });

    for (i = 0; i < 3; i++) {
      var y0 = topArea + i * (cardH + gap);
      var bx = margin + 30;
      var by = y0 + cardH / 2;

      paths.push({ id: 'card' + i, commands: rectPath(margin, y0, cardW, cardH) });
      children.push({ type: 'path', pathId: 'card' + i, fill: '#f4f8fd', stroke: { width: 2, color: '#c9d8ea' } });

      paths.push({ id: 'badge' + i, commands: visualSdk.circle(bx, by, 16) });
      children.push({ type: 'path', pathId: 'badge' + i, fill: accent, stroke: { width: 2, color: accent } });

      if (i < 2) {
        paths.push({ id: 'arrow' + i, commands: downArrowPath(W / 2, y0 + cardH + 4, W / 2, y0 + cardH + gap - 4) });
        children.push({ type: 'path', pathId: 'arrow' + i, fill: 'none', stroke: { width: 2, color: '#7fa3c9' } });
      }
    }

    children.push({ type: 'label', contentId: 'c0', anchor: { x: W / 2, y: 26 }, hAlign: 'center', vAlign: 'middle', color: ink, fontSize: titleFs });

    for (j = 0; j < 3; j++) {
      var cy = topArea + j * (cardH + gap) + cardH / 2;
      children.push({ type: 'label', contentId: 'c' + (1 + j * 3), anchor: { x: margin + 30, y: cy }, hAlign: 'center', vAlign: 'middle', color: '#ffffff', fontSize: numFs });
      children.push({ type: 'label', contentId: 'c' + (2 + j * 3), anchor: { x: margin + 54, y: cy }, hAlign: 'left', vAlign: 'middle', color: ink, fontSize: nameFs });
      children.push({ type: 'label', contentId: 'c' + (3 + j * 3), anchor: { x: W - margin - 18, y: cy }, hAlign: 'right', vAlign: 'middle', color: ink, fontSize: eqFs });
    }

    return {
      schemaVersion: 1,
      sceneId: 'solve-linear-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
